targets.query:
binSize = 0.1

data = from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "perf")
  |> filter(fn: (r) => r["_field"] == "data")
  |> filter(fn: (r) => r["item"] == "HeartbeatRspTime")
  |> filter(fn: (r) => ${sb_flux})
  |> filter(fn: (r) => r._value > 0.0)
  |> keep(columns: ["_time", "_value"])

// Step 1: ç® bin index èåé
binned = data
  |> map(fn: (r) => ({
      r with binIndex: int(v: r._value / binSize)
  }))
  |> map(fn: (r) => ({
      r with 
      binLow: float(v: r.binIndex) * binSize,
      binHigh: (float(v: r.binIndex) + 1.0) * binSize
  }))
  |> map(fn: (r) => ({
      // å¼·å¶æ ¼å¼åçºä¸ä½å°æ¸ (0 â 0.0)
      r with bin: string(v: float(v: int(v: r.binLow * 10.0)) / 10.0) 
                  + "â" +
                  string(v: float(v: int(v: r.binHigh * 10.0)) / 10.0)
  }))
  |> group(columns: ["bin"])
  |> count(column: "_value")
  |> set(key: "joinKey", value: "all")

// Step 2: ç¸½æ¸
total = binned
  |> group()
  |> sum(column: "_value")
  |> set(key: "joinKey", value: "all")

// Step 3: ç®ç¾åæ¯ (ä¿ç 1 ä½å°æ¸)
join(tables: {b: binned, t: total}, on: ["joinKey"])
  |> map(fn: (r) => ({
      bin: if r.bin == "0â0.1" then "0.0â0.1" else r.bin,
      percent: float(v: int(v: (float(v: r._value_b) / float(v: r._value_t) * 1000.0))) / 10.0
  }))
  |> sort(columns: ["bin"])
